/**
 * @param {Array} arr1
 * @param {Array} arr2
 * @return {Array}
 */
var join = function(arr1, arr2) {
    // Map from id -> merged object
    const byId = new Map();

    for (const obj of arr1) {
        // shallow copy so we never mutate the caller's objects
        byId.set(obj.id, { ...obj });
    }

    for (const obj of arr2) {
        if (byId.has(obj.id)) {
            // spread order matters: arr2's keys override arr1's on conflicts
            byId.set(obj.id, { ...byId.get(obj.id), ...obj });
        } else {
            byId.set(obj.id, { ...obj });
        }
    }

    // ids are integers, so a numeric comparator is required
    // (the default sort would compare them as strings)
    return [...byId.values()].sort((a, b) => a.id - b.id);
};
